import { DEFAULT_LOOK, THEMES, type Scheme } from "./look";
import { tokens, type Tokens } from "./tokens";

function block(selector: string, t: Tokens, scheme: Scheme): string {
  const lines = [
    `  color-scheme: ${scheme};`,
    ...Object.entries(t).map(([k, v]) => `  ${k}: ${v};`),
  ];
  return `${selector} {\n${lines.join("\n")}\n}\n`;
}

/** The whole of themes.generated.css: the default theme on :root, then one block per theme. */
export function renderCss(): string {
  const def = THEMES.find((t) => t.id === DEFAULT_LOOK.theme)!;
  return [
    "/* Generated by web/src/theme/css.ts from themes.json. Do not edit by hand:\n" +
      "   run `pnpm --filter @hive-mind/web themes` and commit the result. */\n",
    block(":root", tokens(def.id), def.scheme),
    ...THEMES.map((t) =>
      block(`[data-theme="${t.id}"]`, tokens(t.id), t.scheme),
    ),
  ].join("");
}
